* { box-sizing: border-box; }
body { margin: 0; background: #f5f7fb; color: #182230; font: 16px/1.5 system-ui, sans-serif; }
.shell { max-width: 720px; margin: 4rem auto; padding: 2rem; background: white; border: 1px solid #e1e7ef; border-radius: 12px; box-shadow: 0 8px 24px #1822300d; }
h1 { margin: 0 0 1.5rem; font-size: 2rem; }
form { display: grid; gap: .65rem; }
label { font-weight: 600; }
input { width: 100%; padding: .7rem .8rem; border: 1px solid #aab6c5; border-radius: 6px; font: inherit; }
button { justify-self: start; padding: .6rem .95rem; border: 0; border-radius: 6px; background: #2459c4; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #17459f; }
button:focus-visible, input:focus-visible { outline: 3px solid #8cb4ff; outline-offset: 2px; }
[role="alert"] { margin: 0; color: #a32222; }
section { margin-top: 1.5rem; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: .85rem 0; border-bottom: 1px solid #e5e9ef; }
@media (max-width: 600px) { .shell { margin: 1rem; padding: 1.25rem; } }

